'use strict';

const tax = require('./tax.js');

function totalWithTax(subtotal) {
  const rate = tax.getRate();
  if (rate <= 0) {
    throw new Error('invoice: tax rate not configured (rate=' + rate + ')');
  }
  return Math.round(subtotal * (1 + rate) * 100) / 100;
}

module.exports = { totalWithTax };

