'use strict';
const test = require('node:test');
const assert = require('node:assert');
const tax = require('./src/tax.js');
const invoice = require('./src/invoice.js');

test('unconfigured rate still throws a clear error', () => {
  assert.throws(() => invoice.totalWithTax(100), /not configured/);
});

test('configured rate takes effect', () => {
  tax.setRate(0.07);
  assert.strictEqual(invoice.totalWithTax(100), 107);
});

test('later rate changes take effect', () => {
  tax.setRate(0.2);
  assert.strictEqual(invoice.totalWithTax(50), 60);
});

