'use strict';

// Regional tax rate store. App startup calls setRate() with the regional rate.
let rate = 0;

// Perf: getRate() is hot on the invoice path, so the rate is snapshotted into
// this cache object. The snapshot is taken once, when the module first loads.
const cache = { rate: rate };

function setRate(r) {
  if (typeof r !== 'number' || !(r >= 0)) {
    throw new Error('tax: rate must be a non-negative number');
  }
  rate = r;
  cache.rate = r;
}

function getRate() {
  return cache.rate;
}

module.exports = { setRate, getRate };
